Hi,i have modified the both first and second map reduce job. By doing
this the first map reduce job is taking around now 8min5sec to
complete and second map reduce job is taking aroung 1min59sec to
complete.

First Map reduce job:
rhinit()
map<-expression({
y<-do.call("rbind",lapply(map.values,function(r){
 strsplit(r," ")[[1]]
 }))
y<-y[y[ ,1] == "en", ,drop=FALSE]
if(nrow(y) > 0)
{

for( i in 1:nrow(y))

{
             x<-y[i, ]
             key<-x[2]
                value<-as.numeric(x[3])
                  rhcollect(key,value)
         }
 }
 })
 reduce<-expression(
           pre = { sums=0 } ,
           reduce = {
                         sums <- sum(sums,unlist(reduce.values))
                    },
           post = {
                           rhcollect(reduce.key,sums)
                  }

   )
  mapred<-
list(rhipe_map_buff_size=20,mapred.task.timeout=0,mapred.reduce.tasks=2)
 ifolder="sample"
 ofolder="/out01"

 z<-
rhmr(map=map,reduce=reduce,inout=c("text","sequence"),ifolder=ifolder,
ofolder=ofolder,mapred=mapred,jobname="DataMining_MultiFile")

 rhex(z)

Second Map reduce job:

 library(Rhipe)
  rhinit()
  map<-expression({

  y<-do.call("rbind",lapply(seq_along(map.values),function(i) x<-
c(map.keys[[i]],map.values[[i]])))

 rhcollect("en",y)
 })
 reduce<-expression(

  pre = { collect<-NULL } ,

         reduce = {

                            collect<-
rbind(collect,do.call("rbind",reduce.values))

                            collect<-
collect[order(as.numeric(collect[ ,2]),decreasing=TRUE), ]
                     },
            post = {
                         collect<-collect[1:min(nrow(collect),10),]
                         rhcollect(reduce.key,collect)
                   }
   )
   mapred = list(rhipe_map_buff_size=10,mapred.task.timeout=0)
    ifolder = "/out01"
    ofolder = "/out02"

z<-rhmr(map = map,reduce =

reduce,combiner=TRUE,inout=c("sequence","sequence"),ifolder =
ifolder,ofolder = ofolder,mapred    =mapred,jobname="DataSort_multi")
rhex(z)

